import"./chunks/assets.CDWaORDm.js";import{E as e,at as t,it as n,vt as r}from"./chunks/framework.DwjJr7zi.js";var i=JSON.parse(`{"title":"免流 混淆 零跳 总结(2)","description":"","frontmatter":{"title":"免流 混淆 零跳 总结(2)"},"headers":[],"relativePath":"blog/posts/1387.md","filePath":"blog/posts/1387.md","lastUpdated":1783382106000}`),a={name:`blog/posts/1387.md`};function o(e,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[t(`<h1 id="免流-混淆-零跳-总结-2" tabindex="-1">免流 混淆 零跳 总结(2) <a class="header-anchor" href="#免流-混淆-零跳-总结-2" aria-label="Permalink to “免流 混淆 零跳 总结(2)”">​</a></h1><img class="telegram-media" src="/telegram/AQADgsAxGzz4MVV8.jpg" alt="Telegram 图片" loading="lazy" decoding="async"><div class="telegram-content"><u>免流 混淆 零跳 总结(2)</u><br><br>👉🏻 <a href="/blog/posts/1388">免流 混淆 零跳 总结(1)</a><br><br>确保能被接管的流量都被接管, 分流中该走代理的走代理<br><br>⚠️ 部分方案会有以下情况<br><br> · 断开 Wi-Fi 时, 某些请求继续直连或使用非免流的策略<br><br>可尝试打断请求: <a href="https://t.me/zhetengsha/1513">可能不需要打断请求来解决 Telegram 转圈 / 免流继续跑流量</a><br><br> · IPv6 流量未过代理<br><br> · 代理不支持的情况下 UDP 自动走直连<br><br> · DNS 未过代理<br><br>需要注意 域名 DNS 和节点服务器域名 鸡和蛋的问题<br><br>可在 Sub-Store 中添加节点操作 <code>域名解析</code>, 确保节点服务器为 IP<br><br> · 部分请求不被代理接管(例如绑定物理网卡) 部分代理方案支持包含所有网络请求<br><br>Surge 可使用 <a href="/blog/posts/1394">全自动 包含所有网络设置模块</a><br><br>微信视频语音不免大概是因为 <a href="https://t.me/zhetengsha_group/790078">路由表</a><br><br> · STUN, P2P<br><br>引用 0 跳王刘路: 不追求零跳还是不禁为好，不然微信电话可能打不通. 虎牙哔哩哔哩很多是四位端口 严格就是 1000 开始. 但是微信视频通常用 8000, 禁 10000 以下的 UDP 可能会有问题<br><br>虎牙跳的问题 我加了一些规则到 <a href="https://github.com/xream/rule/blob/release/P2P/README.md">我的 P2P 分流</a> 里面<br>🆕 群友 @SatenRuiko_AC 发现 拒绝 来源非本机&amp;目标为局域网的 请求即可<br><br> · 多 IP 并发和自动检测的策略中存在无法连接的节点时, 拨号失败就建立不起 WS/HTTP 伪装通道的话可能会被认为是通用流量(来自喵佬)<br><br> · QUIC<br><br> · 部分上传(没仔细研究过 有人提过)<br><br> · 部分请求在任何情况下都不走代理(无解)<br><br>⚠️隐藏的小问题<br><br> · 节点或全局屏蔽 QUIC 导致某些国内 App 使用异常<br><br>Surge <code>[General]</code> 里 <code>block-quic = per-policy</code> (这是默认值)<br>国内免流订阅设置 <code>test-url</code> 和 <code>block-quic</code> 示范 <code>🇨🇳 免流 = smart, policy-path=https://a.com, external-policy-modifier=&quot;test-url=http://p11.douyinpic.com,block-quic=off&quot;</code> 其他的自己看着办(<br><br> · Surge 中 Shadowsocks 不支持 UDP over TCP, 与 Shadow TLS 搭配时, UDP 流量侧漏<br><br> · 部分方案中的互联网检测是不走代理的<br><br>使用免流的 URL, 比如 流邦使用 <code>http://p11.douyinpic.com</code><br><br> · 某些分流规则, 常规用法是设置为直连, 但是里面包含了某些域名<br><br>例如 bm7 的 <a href="https://raw.githubusercontent.com/blackmatrix7/ios_rule_script/master/rule/Surge/Lan/Lan.list">Lan</a> 里面有 <code>cp.cloudflare.com</code> 等<br><br> · snell v4 obfs http 在某些情况下不免(未找到根源, 经 P 佬提醒 可能是 <code>reuse</code> 导致的, 应关闭)<br><br><s>各种多路复用都应该关掉?(比如 smux 等) AnyTLS 自带复用, 所以可能也有问题?</s><br><br> · <a href="https://kb.nssurge.com/surge-knowledge-base/zh/release-notes/surge-mac-6-release-note#quic-proxy-mode">snell v5 自带 quic</a>, UDP over UDP 不免. 但是兼容 v4, 客户端设置 <code>version</code> 为 <code>4</code> 即可<br><br> · 部分方案中的自动测速/健康检查总是会自动执行<br><br>如果这个策略组里有节点不是免流节点, 可能会跑通用<br><br> · 部分模块中自带 <code>DIRECT</code> 策略的分流<br><br> · 联通使用百度代理的广州联通俩 IP 不免了<br><br><img class="telegram-custom-emoji" src="/telegram/AgAEDgACMozQVw.webp" alt="🤭" loading="lazy" decoding="async"> <a href="/blog/208/">免流合集</a> <img class="telegram-custom-emoji" src="/telegram/AgADRw4AApYl0Vc.webp" alt="🧐" loading="lazy" decoding="async"> <a href="/blog/">频道资源合集</a> <img class="telegram-custom-emoji" src="/telegram/AgADmw4AArTV0Fc.webp" alt="😄" loading="lazy" decoding="async"> <a href="https://t.me/zhetengsha/957">恰饭推荐</a> <img class="telegram-custom-emoji" src="/telegram/AgAD3A4AAjTykVM.webp" alt="💬" loading="lazy" decoding="async"> <a href="https://t.me/zhetengsha_group">群组</a></div><p class="telegram-source"><a href="https://t.me/zhetengsha/1387">查看 Telegram 原文</a></p>`,4)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};